<template><div class="p-2 rule-page">
 <el-alert v-if="!projectId" title="请先在顶部选择当前物业项目" type="info" :closable="false" show-icon class="mb-2" />
 <template v-else><el-card v-show="showSearch" class="mb-2"><el-form ref="queryRef" :model="query" inline>
  <el-form-item label="所属项目"><el-input :model-value="projectName" disabled /></el-form-item><el-form-item label="规则编码" prop="ruleCode"><el-input v-model="query.ruleCode" clearable /></el-form-item><el-form-item label="规则名称" prop="ruleName"><el-input v-model="query.ruleName" clearable /></el-form-item>
  <el-form-item label="收费项目" prop="chargeItemId"><el-select v-model="query.chargeItemId" clearable><el-option v-for="x in items" :key="x.id" :label="x.itemName" :value="x.id" /></el-select></el-form-item>
  <el-form-item label="计费方式" prop="billingMethod"><el-select v-model="query.billingMethod" clearable><el-option v-for="x in pm_billing_method" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item>
  <el-form-item label="计费周期" prop="billingCycle"><el-select v-model="query.billingCycle" clearable><el-option v-for="x in pm_billing_cycle" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item><el-form-item label="周期模式" prop="cycleMode"><el-select v-model="query.cycleMode" clearable><el-option v-for="x in pm_cycle_mode" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item>
  <el-form-item label="状态" prop="status"><el-select v-model="query.status" clearable><el-option v-for="x in sys_normal_disable" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">搜索</el-button><el-button @click="resetQuery">重置</el-button></el-form-item>
 </el-form></el-card><el-card><template #header><el-row :gutter="10"><el-col :span="1.5"><el-button v-hasPermi="['property:chargeRule:add']" type="primary" plain @click="add">新增</el-button></el-col><el-col :span="1.5"><el-button v-hasPermi="['property:chargeRule:remove']" type="danger" plain :disabled="!ids.length" @click="remove()">删除</el-button></el-col><el-col :span="1.5"><el-button v-hasPermi="['property:chargeRule:export']" type="warning" plain @click="doExport">导出</el-button></el-col><right-toolbar v-model:show-search="showSearch" @query-table="load" /></el-row></template>
  <el-table v-loading="loading" :data="rows" border @selection-change="select"><el-table-column type="selection" width="50"/><el-table-column label="规则编码" prop="ruleCode" min-width="130"><template #default="s"><el-button v-hasPermi="['property:chargeRule:query']" link type="primary" @click="detailOpen(s.row)">{{s.row.ruleCode}}</el-button></template></el-table-column><el-table-column label="规则名称" prop="ruleName" min-width="150"/><el-table-column label="收费项目" prop="chargeItemName" min-width="150"/>
   <el-table-column label="计费方式"><template #default="s"><dict-tag :options="pm_billing_method" :value="s.row.billingMethod"/></template></el-table-column><el-table-column label="账单周期"><template #default="s"><dict-tag :options="pm_billing_cycle" :value="s.row.billingCycle"/></template></el-table-column><el-table-column label="计价周期"><template #default="s"><dict-tag :options="pm_billing_cycle" :value="s.row.priceCycle"/></template></el-table-column><el-table-column label="周期模式"><template #default="s"><dict-tag :options="pm_cycle_mode" :value="s.row.cycleMode"/></template></el-table-column><el-table-column label="应缴日" min-width="150"><template #default="s"><dict-tag :options="pm_due_date_mode" :value="s.row.dueDateMode"/> {{s.row.dueDateOffsetDays}} 天</template></el-table-column>
   <el-table-column label="计费标准" min-width="130"><template #default="s">{{ standard(s.row) }}</template></el-table-column><el-table-column label="有效期" min-width="190"><template #default="s">{{ s.row.effectiveStartDate }} 至 {{ s.row.effectiveEndDate||'长期' }}</template></el-table-column>
   <el-table-column label="状态" width="80"><template #default="s"><el-switch v-model="s.row.status" active-value="0" inactive-value="1" @change="status(s.row)"/></template></el-table-column><el-table-column label="操作" width="120" fixed="right"><template #default="s"><el-button v-hasPermi="['property:chargeRule:edit']" link type="primary" @click="edit(s.row)">修改</el-button><el-button v-hasPermi="['property:chargeRule:remove']" link type="danger" @click="remove(s.row)">删除</el-button></template></el-table-column>
  </el-table><pagination v-show="total>0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/></el-card></template>
 <el-dialog v-model="dialog.visible" :title="dialog.title" width="760px"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-row :gutter="20">
  <el-col :span="12"><el-form-item label="所属项目" prop="projectId"><el-input :model-value="projectName" disabled /></el-form-item></el-col><el-col :span="12"><el-form-item label="收费项目" prop="chargeItemId"><el-select v-model="form.chargeItemId"><el-option v-for="x in items" :key="x.id" :label="x.itemName" :value="x.id"/></el-select></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="规则编码" prop="ruleCode"><el-input v-model="form.ruleCode" :disabled="!!form.id"/></el-form-item></el-col><el-col :span="12"><el-form-item label="规则名称" prop="ruleName"><el-input v-model="form.ruleName"/></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="计费方式" prop="billingMethod"><el-select v-model="form.billingMethod" @change="methodChanged"><el-option v-for="x in pm_billing_method" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col>
  <el-col :span="12"><el-form-item v-if="form.billingMethod==='AREA'" label="单价(元/㎡)" prop="unitPrice"><el-input-number v-model="form.unitPrice" :min="0" :precision="6"/></el-form-item><el-form-item v-else-if="form.billingMethod==='FIXED'" label="固定金额" prop="fixedAmount"><el-input-number v-model="form.fixedAmount" :min="0" :precision="2"/></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="账单周期" prop="billingCycle"><el-select v-model="form.billingCycle"><el-option v-for="x in pm_billing_cycle" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="计价周期" prop="priceCycle"><el-select v-model="form.priceCycle"><el-option v-for="x in pm_billing_cycle" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="周期模式" prop="cycleMode"><el-select v-model="form.cycleMode"><el-option v-for="x in pm_cycle_mode" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="应缴日模式" prop="dueDateMode"><el-select v-model="form.dueDateMode"><el-option v-for="x in pm_due_date_mode" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="偏移天数" prop="dueDateOffsetDays"><el-input-number v-model="form.dueDateOffsetDays" :min="0" :max="7" :precision="0"/></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="生效日期" prop="effectiveStartDate"><el-date-picker v-model="form.effectiveStartDate" type="date" value-format="YYYY-MM-DD"/></el-form-item></el-col><el-col :span="12"><el-form-item label="失效日期"><el-date-picker v-model="form.effectiveEndDate" type="date" value-format="YYYY-MM-DD"/></el-form-item></el-col>
  <el-col :span="12"><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio v-for="x in sys_normal_disable" :key="x.value" :value="x.value">{{x.label}}</el-radio></el-radio-group></el-form-item></el-col><el-col :span="12"><el-form-item label="排序"><el-input-number v-model="form.sort" :min="0"/></el-form-item></el-col><el-col :span="24"><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-col>
 </el-row></el-form><template #footer><el-button type="primary" :loading="saving" @click="submit">确定</el-button><el-button @click="cancel">取消</el-button></template></el-dialog>
 <el-dialog v-model="detailVisible" title="计费规则详情" width="720px"><el-descriptions v-if="detail" :column="2" border><el-descriptions-item label="所属项目">{{detail.projectName}}</el-descriptions-item><el-descriptions-item label="收费项目">{{detail.chargeItemName}}</el-descriptions-item><el-descriptions-item label="规则编码">{{detail.ruleCode}}</el-descriptions-item><el-descriptions-item label="规则名称">{{detail.ruleName}}</el-descriptions-item><el-descriptions-item label="计费方式"><dict-tag :options="pm_billing_method" :value="detail.billingMethod"/></el-descriptions-item><el-descriptions-item label="计费标准">{{standard(detail)}}</el-descriptions-item><el-descriptions-item label="账单周期"><dict-tag :options="pm_billing_cycle" :value="detail.billingCycle"/></el-descriptions-item><el-descriptions-item label="计价周期"><dict-tag :options="pm_billing_cycle" :value="detail.priceCycle"/></el-descriptions-item><el-descriptions-item label="周期模式"><dict-tag :options="pm_cycle_mode" :value="detail.cycleMode"/></el-descriptions-item><el-descriptions-item label="应缴日"><dict-tag :options="pm_due_date_mode" :value="detail.dueDateMode"/> {{detail.dueDateOffsetDays}} 天</el-descriptions-item><el-descriptions-item label="生效日期">{{detail.effectiveStartDate}}</el-descriptions-item><el-descriptions-item label="失效日期">{{detail.effectiveEndDate||'长期'}}</el-descriptions-item><el-descriptions-item label="状态"><dict-tag :options="sys_normal_disable" :value="detail.status"/></el-descriptions-item><el-descriptions-item label="备注">{{detail.remark||'-'}}</el-descriptions-item></el-descriptions></el-dialog>
</div></template>
<script setup name="ChargeRule" lang="ts">
import {addChargeRule,changeChargeRuleStatus,delChargeRule,exportChargeRule,getChargeRule,listChargeRule,updateChargeRule} from '@/api/property/charge/rule'; import type {ChargeRuleForm,ChargeRuleQuery,ChargeRuleVO} from '@/api/property/charge/rule/types'; import {chargeItemOptions,financeProjectOptions} from '@/api/property/charge/item'; import type {ChargeItemOptionVO} from '@/api/property/charge/item/types'; import {useFormDialog} from '@/hooks/dialog/useFormDialog'; import {useSearchToggle} from '@/hooks/form/useSearchToggle'; import modal from '@/plugins/modal'; import {useCurrentProjectStore} from '@/store/modules/currentProject'; import {useDict} from '@/utils/dict';
const {pm_billing_method,pm_billing_cycle,pm_cycle_mode,pm_due_date_mode,sys_normal_disable}=toRefs<any>(useDict('pm_billing_method','pm_billing_cycle','pm_cycle_mode','pm_due_date_mode','sys_normal_disable'));const store=useCurrentProjectStore(),projectId=computed(()=>store.currentProjectId),projectName=computed(()=>store.currentProjectName),rows=ref<ChargeRuleVO[]>([]),items=ref<ChargeItemOptionVO[]>([]),ids=ref<(number|string)[]>([]),detail=ref<ChargeRuleVO>(),detailVisible=ref(false),total=ref(0),loading=ref(false),saving=ref(false),queryRef=ref<ElFormInstance>(),formRef=ref<ElFormInstance>();let version=0;const dialogProject=ref<number|string>();const {showSearch}=useSearchToggle();
const blank=():ChargeRuleForm=>({projectId:undefined,chargeItemId:undefined,ruleCode:'',ruleName:'',billingMethod:undefined,billingCycle:undefined,priceCycle:'MONTH',cycleMode:undefined,dueDateMode:'AFTER_PERIOD_START',dueDateOffsetDays:0,unitPrice:undefined,fixedAmount:undefined,effectiveStartDate:undefined,effectiveEndDate:undefined,status:'0',sort:0,remark:''});const data=reactive({form:blank(),query:{pageNum:1,pageSize:10} as ChargeRuleQuery,rules:{projectId:[{required:true,message:'所属项目不能为空'}],chargeItemId:[{required:true,message:'收费项目不能为空'}],ruleCode:[{required:true,message:'规则编码不能为空'}],ruleName:[{required:true,message:'规则名称不能为空'}],billingMethod:[{required:true,message:'计费方式不能为空'}],billingCycle:[{required:true,message:'账单周期不能为空'}],priceCycle:[{required:true,message:'计价周期不能为空'}],cycleMode:[{required:true,message:'周期模式不能为空'}],dueDateMode:[{required:true,message:'应缴日模式不能为空'}],dueDateOffsetDays:[{required:true,message:'偏移天数不能为空'}],effectiveStartDate:[{required:true,message:'生效日期不能为空'}],unitPrice:[{required:true,message:'单价不能为空'}],fixedAmount:[{required:true,message:'固定金额不能为空'}]}});const {form,query,rules}=toRefs(data);const {dialog,resetForm,showDialog,closeDialog}=useFormDialog({form,formRef,initialFormData:blank()});const active=(v:number,p:number|string)=>v===version&&String(projectId.value)===String(p);
async function load(){const p=projectId.value,v=++version;if(!p){rows.value=[];total.value=0;return}loading.value=true;try{const [ps,opts]=await Promise.all([financeProjectOptions(),chargeItemOptions({projectId:p,chargeType:'PERIODIC'})]);if(!active(v,p))return;if(!(ps.data||[]).some(x=>String(x.id)===String(p))){rows.value=[];return}items.value=opts.data||[];const r=await listChargeRule({...query.value,projectId:p});if(active(v,p)){rows.value=r.data?.rows||[];total.value=r.data?.total||0}}finally{if(v===version)loading.value=false}}
const search=()=>{query.value.pageNum=1;load()},resetQuery=()=>{queryRef.value?.resetFields();search()},select=(x:ChargeRuleVO[])=>ids.value=x.map(y=>y.id);function add(){const currentProjectId=projectId.value;if(!currentProjectId)return modal.msgWarning('请先选择项目');resetForm();form.value.projectId=currentProjectId;dialogProject.value=currentProjectId;showDialog('新增计费规则')}async function edit(row:any){const p=projectId.value,v=++version;if(!p)return;const r=await getChargeRule(row.id);if(!active(v,p))return;resetForm();Object.assign(form.value,r.data);dialogProject.value=p;showDialog('修改计费规则')}function cancel(){closeDialog();resetForm();dialogProject.value=undefined}function methodChanged(){if(form.value.billingMethod==='AREA')form.value.fixedAmount=undefined;else form.value.unitPrice=undefined}
async function detailOpen(row:any){const p=projectId.value,v=++version;if(!p)return;const r=await getChargeRule(row.id);if(active(v,p)){detail.value=r.data;detailVisible.value=true}}
const submit=async()=>{const currentProjectId=projectId.value;if(!currentProjectId||String(dialogProject.value)!==String(currentProjectId)){modal.msgWarning('当前项目无效，请重新选择项目');cancel();return}if(!form.value.projectId)form.value.projectId=currentProjectId;if(String(form.value.projectId)!==String(currentProjectId)){modal.msgWarning('当前项目已切换，请重新操作');cancel();return}const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;saving.value=true;try{form.value.id?await updateChargeRule(form.value):await addChargeRule({...form.value,projectId:form.value.projectId});modal.msgSuccess('操作成功');cancel();await load()}finally{saving.value=false}};async function status(row:any){const target=row.status;try{await changeChargeRuleStatus({id:row.id,status:target});modal.msgSuccess('操作成功')}catch{row.status=target==='0'?'1':'0'}}async function remove(row?:any){await modal.confirm('确认删除选中的计费规则吗？');await delChargeRule(row?.id||ids.value);modal.msgSuccess('删除成功');await load()}const doExport=()=>projectId.value&&exportChargeRule({...query.value,projectId:projectId.value});const standard=(r:any)=>r.billingMethod==='AREA'?`${r.unitPrice} 元/㎡`:`${r.fixedAmount} 元/周期`;watch(projectId,()=>{version++;cancel();detailVisible.value=false;rows.value=[];items.value=[];query.value={pageNum:1,pageSize:10};load()});onMounted(load);onBeforeUnmount(()=>version++);
</script><style scoped>.rule-page :deep(.el-select){width:210px}.rule-page :deep(.el-input-number){width:100%}</style>
